#include <stddef.h>
#include <stdio.h>

int copy_ints(int *destination, size_t capacity, const int *source, size_t count) {
    if (destination == NULL || source == NULL || count > capacity) return 0;
    for (size_t i = 0; i < count; ++i) destination[i] = source[i];
    return 1;
}

int main(void) {
    int src[] = {2, 4}; int dst[2] = {0};
    if (!copy_ints(dst, 2, src, 2)) return 1;
    printf("%d %d\n", dst[0], dst[1]); return 0;
}
